import type { ControlUiSkin } from "@/components/control-ui/skin";

export const skin: ControlUiSkin = {
  id: "modern-apple",
  sidebarLayout: "sidebar",
  scrollAreaBlur: true,
};

[data-skin="modern-apple"] {
  --hairline: var(--border);
  --apple-glass-refraction: blur(0px);
  --apple-glass-luminance: brightness(1);
  --glass-fill: oklch(1 0 0 / 0.72);
  --glass-fill-hover: oklch(1 0 0 / 0.9);
  --glass-fill-active: oklch(0.92 0 0 / 0.8);
  --glass-rim: oklch(0 0 0 / 0.08);
  --glass-gloss: oklch(1 0 0 / 0.85);
  --backdrop-blur-glass: var(--backdrop-blur-popover);
  --segmented-bg: oklch(0 0 0 / 0.055);
  --segmented-active-bg: oklch(1 0 0 / 0.95);
  --canvas-gradient: linear-gradient(165deg, oklch(0.97 0.004 250), oklch(0.93 0.008 255));
  --apple-sidebar-float-gap: 0.75rem;
  --apple-sidebar-material: oklch(0.92 0 0);
  --apple-sidebar-background: oklch(from var(--apple-sidebar-material) l c h / 0.92);
  --apple-sidebar-backdrop-filter: blur(80px) saturate(0.15);
  --apple-sidebar-selection: oklch(0 0 0 / 0.075);
  --apple-sidebar-hover: oklch(0 0 0 / 0.035);
  --apple-sidebar-foreground: var(--foreground);
  --apple-sidebar-label: var(--muted-foreground);
  --apple-sidebar-icon: var(--primary);
  --_apple-popup-fill: oklch(1 0 0 / var(--popover-opacity));
  --surface-gloss: oklch(1 0 0 / 0.9);
  --surface-hairline: oklch(0 0 0 / 0.42);
  --apple-glass-edge-shadow:
    0 0 0 0.5px var(--surface-hairline),
    inset 0 0 0 1px var(--surface-gloss),
    inset 0 2px 1px -0.5px oklch(1 0 0 / 0.95),
    inset 0 -1px 0 oklch(1 0 0 / 0.6),
    inset 1px 0 2px oklch(1 0 0 / 0.35),
    inset -1px 0 2px oklch(0 0 0 / 0.08),
    inset 0 4px 8px -5px oklch(0 0 0 / 0.2),
    inset 0 -5px 10px -7px oklch(0 0 0 / 0.28);
  --apple-liquid-shadow:
    var(--apple-glass-edge-shadow), 0 12px 40px -8px oklch(from var(--shadow-color) l c h / 0.28),
    0 3px 10px -3px oklch(from var(--shadow-color) l c h / 0.2);
  --apple-liquid-modal-shadow:
    var(--apple-glass-edge-shadow), 0 24px 72px -16px oklch(from var(--shadow-color) l c h / 0.3),
    0 6px 20px -6px oklch(from var(--shadow-color) l c h / 0.18);
  --menu-shadow: var(--apple-liquid-shadow);
  --apple-control-shadow:
    inset 0 0 0 0.5px var(--glass-rim), inset 0 1px 0 var(--glass-gloss), inset 0 -1px 1px oklch(0 0 0 / 0.04),
    0 2px 4px -2px oklch(0 0 0 / 0.16);
}

@supports (backdrop-filter: url("")) {
  [data-skin="modern-apple"]:has(#cui-modern-apple-refraction),
  :root:has(#cui-modern-apple-refraction) [data-skin="modern-apple"] {
    --apple-glass-refraction: url("#cui-modern-apple-refraction");
  }
}

:where(.dark) [data-skin="modern-apple"],
.dark[data-skin="modern-apple"] {
  --glass-fill: oklch(0.42 0.003 260 / 0.65);
  --glass-fill-hover: oklch(0.4 0.003 260 / 0.75);
  --glass-fill-active: oklch(0.35 0.003 260 / 0.75);
  --glass-rim: oklch(1 0 0 / 0.1);
  --glass-gloss: oklch(1 0 0 / 0.16);
  --segmented-bg: oklch(0 0 0 / 0.22);
  --segmented-active-bg: oklch(0.46 0.003 260 / 0.8);
  --canvas-gradient: linear-gradient(165deg, oklch(0.27 0.006 255), oklch(0.2 0.004 255));
  --_apple-popup-fill: oklch(0.46 0.012 280 / var(--popover-opacity));
  --apple-sidebar-material: oklch(0.195 0.003 264);
  --apple-sidebar-selection: oklch(1 0 0 / 0.12);
  --apple-sidebar-hover: oklch(1 0 0 / 0.06);
  --apple-sidebar-foreground: oklch(0.89 0.004 260);
  --apple-sidebar-label: oklch(0.68 0.008 250);
  --apple-sidebar-icon: oklch(from var(--primary) max(l, 0.7) c h);
  --apple-glass-luminance: brightness(0.55);
  --surface-gloss: oklch(1 0 0 / 0.26);
  --surface-hairline: oklch(0 0 0 / 0.92);
  --apple-glass-edge-shadow:
    0 0 0 1px var(--surface-hairline),
    inset 0 0 0 0.5px var(--surface-gloss),
    inset 0 1px 1px -0.25px oklch(1 0 0 / 0.32),
    inset 0 -1px 0 oklch(1 0 0 / 0.1),
    inset 1px 0 2px oklch(1 0 0 / 0.06),
    inset -1px 0 2px oklch(0 0 0 / 0.18),
    inset 0 4px 8px -5px oklch(0 0 0 / 0.3),
    inset 0 -5px 10px -7px oklch(0 0 0 / 0.36);
  --apple-liquid-shadow: var(--apple-glass-edge-shadow), 0 12px 44px -8px oklch(0 0 0 / 0.55), 0 2px 10px -3px oklch(0 0 0 / 0.4);
  --apple-liquid-modal-shadow: var(--apple-glass-edge-shadow), 0 28px 72px -16px oklch(0 0 0 / 0.6), 0 6px 20px -6px oklch(0 0 0 / 0.45);
}

@layer components {
  [data-skin="modern-apple"] .apple-glass {
    background-color: oklch(from var(--popover) l c h / var(--popover-opacity));
    -webkit-backdrop-filter: blur(var(--backdrop-blur-popover)) saturate(1.8);
    backdrop-filter: blur(var(--backdrop-blur-popover)) saturate(1.8);
    box-shadow: inset 0 1px 0 0 var(--glass-gloss);
  }

  [data-skin="modern-apple"]
    [data-slot="root"][data-variant="floating"][data-control-family="sidebar"]
    [data-slot="container"][data-control-family="sidebar"] {
    padding: var(--apple-sidebar-float-gap);
    overflow: visible;
  }

  [data-skin="modern-apple"] [data-slot="root"][data-variant="floating"][data-control-family="sidebar"] {
    --cui-sidebar-inner-border-width: 0px;
    --cui-sidebar-inner-background: var(--apple-sidebar-background);
    --cui-sidebar-inner-shadow:
      inset 0 1px 0 0 var(--surface-gloss), inset 0 0 0 0.5px var(--surface-hairline), 0 3px 12px -1px oklch(0 0 0 / 0.14),
      0 1px 4px oklch(0 0 0 / 0.08);
  }

  [data-skin="modern-apple"]
    [data-slot="root"][data-variant="floating"][data-collapsible="icon"][data-control-family="sidebar"]
    [data-slot="gap"][data-control-family="sidebar"],
  [data-skin="modern-apple"]
    [data-slot="root"][data-variant="floating"][data-collapsible="icon"][data-control-family="sidebar"]
    [data-slot="container"][data-control-family="sidebar"] {
    width: calc(var(--sidebar-width-icon) + var(--apple-sidebar-float-gap) * 2 + 2px);
  }

  [data-skin="modern-apple"] :where([data-slot="wrapper"][data-control-family="sidebar"]) {
    --cui-sidebar-wrapper-background-image: var(--canvas-gradient);
    --cui-sidebar-inset-background: var(--background);
    --cui-sidebar-inset-background-image: none;
    --cui-sidebar-inset-shadow: none;
    background-attachment: fixed;
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="sidebar"]) {
    --sidebar: transparent;
    --cui-sidebar-inner-background: var(--apple-sidebar-background);
    --cui-sidebar-inner-border-color: var(--glass-rim);
    --cui-sidebar-inner-backdrop-filter: var(--apple-sidebar-backdrop-filter);
    --cui-sidebar-inner-border-width: 0px;
    --cui-sidebar-inner-radius: 0px;
    --cui-sidebar-group-label-foreground: var(--apple-sidebar-label);
    --cui-sidebar-menu-button-radius: 0.375rem;
    --cui-sidebar-menu-button-foreground: var(--apple-sidebar-foreground);
    --cui-sidebar-menu-button-hover-background: var(--apple-sidebar-hover);
    --cui-sidebar-menu-button-hover-foreground: var(--foreground);
    --cui-sidebar-menu-button-active-background: var(--apple-sidebar-selection);
    --cui-sidebar-menu-button-active-foreground: var(--foreground);
  }

  [data-skin="modern-apple"] :where([data-control-family="sidebar"][data-slot="menu-button"]) {
    font-size: var(--text-label);
  }

  [data-skin="modern-apple"] :where([data-control-family="sidebar"][data-slot="menu-button"][data-active]),
  [data-skin="modern-apple"] :where([data-control-family="sidebar"][data-slot="group-label"]) {
    font-weight: 600;
  }

  [data-skin="modern-apple"]
    :where([data-control-family="sidebar"][data-slot="menu-button"], [data-control-family="sidebar"][data-slot="group-label"])
    > svg:first-child {
    color: var(--apple-sidebar-icon);
  }

  [data-skin="modern-apple"]
    :where([data-control-family="sidebar"][data-slot="menu-track"])
    > :where([data-control-family="track-highlight"][data-slot="root"]) {
    --cui-track-highlight-background: var(--cui-sidebar-menu-button-active-background);
    --cui-track-highlight-hover-background: var(--cui-sidebar-menu-button-hover-background);
    --cui-track-highlight-radius: var(--cui-sidebar-menu-button-radius);
    --cui-track-highlight-ring-color: transparent;
    --cui-track-highlight-shadow: none;
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="sidebar"][data-variant="floating"]) {
    --cui-sidebar-inner-radius: var(--radius-panel);
  }

  [data-skin="modern-apple"] :where([data-slot="inset"][data-control-family="sidebar"]) {
    background-attachment: fixed;
  }

  [data-skin="modern-apple"] [data-slot="content"][data-control-family="sidebar-layout"] {
    margin: 0;
    border-width: 0;
    border-radius: 0;
    background-color: transparent;
    box-shadow: none;
  }

  [data-skin="modern-apple"] :where([data-control-family="button"][data-control="true"]) {
    --cui-button-press-scale: 0.97;
  }

  [data-skin="modern-apple"] :where([data-control-family="button"][data-control="true"][data-variant="surface"]) {
    --cui-button-background: var(--glass-fill);
    --cui-button-hover-background: var(--glass-fill-hover);
    --cui-button-press-background: var(--glass-fill-active);
    --cui-button-shadow: var(--apple-control-shadow);
    -webkit-backdrop-filter: blur(var(--backdrop-blur-glass)) saturate(1.5);
    backdrop-filter: blur(var(--backdrop-blur-glass)) saturate(1.5);
  }

  [data-skin="modern-apple"] :where([data-control-family="button"][data-control="true"][data-variant="solid"]) {
    --cui-button-hover-background: var(--cui-button-background);
    --cui-button-hover-foreground: var(--cui-button-foreground);
    --cui-button-shadow: inset 0 1px 0 oklch(1 0 0 / 0.2), inset 0 -1px 0 oklch(0 0 0 / 0.12), 0 2px 4px -2px oklch(0 0 0 / 0.2);
  }

  [data-skin="modern-apple"]
    :where(
      [data-slot="root"][data-variant="inverse"][data-control-family="toolbar"]
        [data-control-ui="button"][data-slot="root"][data-control-family="button"]
    ) {
    --cui-button-background: transparent;
    --cui-button-foreground: oklch(from var(--background) l c h / 0.7);
    --cui-button-hover-background: oklch(from var(--background) l c h / 0.1);
    --cui-button-hover-foreground: var(--background);
    --cui-button-press-background: oklch(from var(--background) l c h / 0.12);
    --cui-button-active-background: var(--background);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-background: var(--background);
    --cui-button-shadow: 0 0 transparent;
    --cui-button-active-shadow: 0 0 transparent;
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="tabs"]) {
    --cui-tabs-trigger-radius: 0.5625rem;
    --cui-tabs-list-padding: 0.125rem;
    --cui-tabs-list-background: var(--segmented-bg);
    --cui-tabs-list-shadow: inset 0 1px 2px oklch(0 0 0 / 0.08);
    --cui-tabs-list-backdrop-filter: blur(var(--backdrop-blur-glass));
    --cui-tabs-border-color: var(--hairline);
    --cui-tabs-indicator-background: var(--segmented-active-bg);
    --cui-tabs-indicator-shadow:
      inset 0 1px 0 0 var(--glass-gloss), 0 1px 3px oklch(from var(--shadow-color) l c h / 0.18),
      0 0 0 0.5px oklch(from var(--shadow-color) l c h / 0.04);
  }
}

@layer components {
  [data-skin="modern-apple"]
    :where([data-control-family="popup"][data-popup-part="surface"], [data-control-family="popup"][data-popup-part="list-surface"]) {
    --cui-popup-radius: var(--radius-popover);
    --cui-popup-border-width: 0px;
  }

  [data-skin="modern-apple"]
    :where(
      [data-control-family="popup"][data-slot][data-popup-part="surface"][data-surface="floating"]:not([data-popup-kind="tooltip"]),
      [data-control-family="popup"][data-slot][data-popup-part="surface"][data-surface="modal"],
      [data-control-family="popup"][data-slot][data-popup-part="list-surface"][data-surface="floating"]
    ) {
    --cui-popup-background: var(--_apple-popup-fill);
    --cui-popup-shadow: var(--menu-shadow);
    --cui-popup-backdrop-filter: blur(var(--backdrop-blur-popover)) saturate(1.5) var(--apple-glass-luminance) var(--apple-glass-refraction);
  }

  [data-skin="modern-apple"] :where([data-control-family="popup"][data-slot][data-popup-part="surface"][data-surface="modal"]) {
    --cui-popup-shadow: var(--apple-liquid-modal-shadow);
  }

  [data-skin="modern-apple"] :where([data-control-family="popup"][data-slot="description"]) {
    color: var(--cui-popup-foreground);
  }

  [data-skin="modern-apple"] :where([data-popup-part="list-surface"]) {
    padding: var(--popover-padding);
  }

  [data-skin="modern-apple"] :where([data-popup-part="item"]) {
    min-height: 1.5rem;
    padding-block: 0.125rem;
    font-size: var(--text-label);
    font-weight: 500;
  }

  [data-skin="modern-apple"] :where([data-popup-part="label"]) {
    padding-block: 0.25rem;
    font-size: var(--text-label);
    font-weight: 600;
    letter-spacing: normal;
    text-transform: none;
  }

  [data-skin="modern-apple"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"],
      [data-control-family="popup"][data-popup-part="list-surface"],
      [data-control-family="popup"][data-popup-part="bar"]
    ) {
    --cui-popup-item-radius: var(--radius-popup-item);
    --cui-popup-item-highlight-background: var(--active-fill);
    --cui-popup-item-highlight-foreground: var(--foreground);
    --cui-popup-item-highlight-muted-foreground: var(--foreground);
    --cui-popup-item-disabled-opacity: 0.4;
    --cui-popup-separator-color: var(--hairline);
  }

  [data-skin="modern-apple"] :where([data-popup-part="separator"]) {
    margin-inline: 0;
  }

  [data-skin="modern-apple"] :where([data-popup-part="shortcut"]) {
    margin-inline-start: auto;
    font-size: var(--text-caption);
    letter-spacing: normal;
  }

  [data-skin="modern-apple"] :where([data-control-family="popup"][data-slot][data-popup-part="surface"][data-surface="modal"]) {
    --cui-popup-radius: var(--radius-panel);
    --cui-popup-shadow: var(--apple-liquid-modal-shadow);
  }

  [data-skin="modern-apple"] :where([data-control-ui="dialog"][data-slot="title"][data-control-family="popup"]) {
    font-size: 0.9375rem;
    font-weight: 600;
  }
}

@layer components {
  [data-skin="modern-apple"] :where([data-control-family="field"][data-control="true"]) {
    --cui-field-radius: var(--radius-control);
    --cui-field-background: oklch(from var(--background) l c h / 0.55);
    --cui-field-foreground: var(--foreground);
    --cui-field-border-color: var(--input);
    --cui-field-border-width: 1px;
    --cui-field-backdrop-filter: none;
    --cui-field-shadow: inset 0 1px 2px oklch(0 0 0 / 0.04);
    --cui-field-focus-border-color: var(--primary);
  }
}
@layer components {
  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="thread-rail"]) {
    --cui-thread-rail-popover-radius: var(--radius-lg);
  }

  [data-skin="modern-apple"] :where([data-control-family="thread-rail"][data-slot="popover"][data-surface="floating"]) {
    --cui-thread-rail-popover-background: var(--_apple-popup-fill);
    --cui-thread-rail-popover-border-width: 0px;
    --cui-thread-rail-popover-shadow: var(--menu-shadow);
    --cui-thread-rail-popover-backdrop-blur: var(--backdrop-blur-popover);
  }

  [data-skin="modern-apple"] :where([data-control-ui="slider"][data-slot="root"][data-control-family="range"]) {
    --cui-range-indicator-background: var(--primary);
    --cui-range-thumb-radius: 9999px;
    --cui-range-thumb-background: oklch(1 0 0);
    --cui-range-thumb-border-color: var(--glass-rim);
    --cui-range-thumb-shadow: 0 1px 3px oklch(0 0 0 / 0.28);
  }

  [data-skin="modern-apple"] :where([data-control-family="switch"][data-slot="root"]) {
    --corner-shape: round;
    --cui-switch-inline-size: 3.375rem;
    --cui-switch-height: 1.5rem;
    --cui-switch-thumb-inline-size: 2rem;
    --cui-switch-padding: 0.125rem;
    --cui-switch-background: oklch(from var(--foreground) l c h / 0.085);
    --cui-switch-hover-background: oklch(from var(--foreground) l c h / 0.11);
    --cui-switch-thumb-background: oklch(1 0 0);
    --cui-switch-thumb-shadow: 0 3px 36px oklch(0 0 0 / 0.05);
    --cui-switch-thumb-press-scale: 1.12 1.2;
  }

  [data-skin="modern-apple"] :where([data-control-family="switch"][data-slot="root"]:is(:active, [data-dragging])) {
    --cui-switch-background: oklch(from var(--foreground) l c h / 0.16);
    --cui-switch-checked-background: oklch(from var(--primary) calc(l * 0.95) c h);
  }

  @supports (backdrop-filter: blur(1px)) {
    [data-skin="modern-apple"]
      :where([data-control-family="switch"][data-slot="root"]:is(:active, [data-dragging]):not([data-disabled], [data-readonly])) {
      --cui-switch-thumb-background: oklch(1 0 0 / 0.3);
      --cui-switch-thumb-backdrop-filter: blur(2px) saturate(1.5);
      --cui-switch-thumb-shadow:
        inset 0 0 0 1px oklch(1 0 0 / 0.65), inset 0 1px 1px oklch(1 0 0 / 0.9), inset 0 -1px 2px oklch(0 0 0 / 0.15),
        0 2px 8px oklch(0 0 0 / 0.15);
    }
  }

  @media (prefers-reduced-transparency: reduce), (forced-colors: active) {
    [data-skin="modern-apple"] :where([data-control-family="sidebar"][data-slot="root"]) {
      --cui-sidebar-inner-background: var(--apple-sidebar-material);
      --cui-sidebar-inner-backdrop-filter: none;
    }

    [data-skin="modern-apple"] :where([data-control-family="switch"][data-slot="root"]:is(:active, [data-dragging])) {
      --cui-switch-thumb-background: oklch(1 0 0);
      --cui-switch-thumb-backdrop-filter: none;
    }
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-role="user"][data-control-family="chat-message"]) {
    --cui-chat-message-radius: var(--radius-field);
    --cui-chat-message-corner-radius: var(--radius-field);
    --cui-chat-message-background: var(--primary);
    --cui-chat-message-foreground: var(--primary-foreground);
    --cui-chat-message-shadow: none;
  }

  [data-skin="modern-apple"] :where([data-control-ui="chat-composer"][data-slot="root"][data-control-family="chat-composer"]) {
    --cui-chat-composer-shell-background: oklch(from var(--background) l c h / 0.75);
    --cui-chat-composer-shell-backdrop-filter: blur(var(--backdrop-blur-glass)) saturate(1.8);
    --cui-chat-composer-shell-border-color: var(--input);
    --cui-chat-composer-shell-radius: var(--radius-control);
    --cui-chat-composer-shell-shadow: var(--shadow-inset);
    --cui-chat-composer-input-foreground: var(--foreground);
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="markdown-block"]) {
    --cui-markdown-block-border-color: var(--glass-rim);
  }

  [data-skin="modern-apple"] :where([data-control-ui="chat-layout"][data-slot="root"][data-control-family="chat-layout"]) {
    --cui-chat-layout-background: var(--card);
    --cui-chat-layout-border-color: var(--border);
    --cui-chat-layout-shadow: none;
  }
}

[data-skin="modern-apple"][data-skin] {
  --font-sans: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --font-mono: "SF Mono", ui-monospace, SFMono-Regular, Menlo, monospace;

  --text-micro: 0.6875rem;
  --text-caption: 0.75rem;
  --text-label: 0.8125rem;
  --text-body-lg: 1.0625rem;
  --text-heading-1: 2rem;
  --text-heading-1--font-weight: 600;
  --text-heading-1--letter-spacing: -0.025em;
  --text-display: 2.5rem;
  --text-display--letter-spacing: -0.03em;

  --background: oklch(1 0 0);
  --foreground: oklch(0.2178 0 89.876);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.2178 0 89.876);
  --popover: oklch(0.995 0 0);
  --popover-foreground: oklch(0.2178 0 89.876);
  --primary: oklch(0.556 0.2018 254.088);
  --primary-foreground: oklch(1 0 0);
  --muted: oklch(0.9673 0.0024 286.354);
  --muted-foreground: oklch(0.47 0 0);
  --secondary: oklch(0.9364 0.0027 286.347);
  --secondary-foreground: oklch(0.2178 0 89.876);
  --accent: oklch(0.9673 0.0024 286.354);
  --accent-foreground: oklch(0.2178 0 89.876);
  --destructive: oklch(0.583 0.2328 25.739);
  --destructive-foreground: oklch(1 0 0);

  --ring-opacity: 0.12;
  --border: oklch(0 0 0 / var(--ring-opacity));
  --input: oklch(0 0 0 / 0.16);
  --ring: var(--primary);
  --focus-ring: var(--primary);
  --focus-ring-width: 2px;
  --focus-ring-offset: 2px;

  --canvas: oklch(0.9466 0 0);

  --popover-opacity: 0.36;
  --backdrop-blur-popover: 3px;

  --overlay-opacity: 0.2;
